constraints:
1 ≤ N ≤ 10^{5}
0 ≤ K ≤ 10^{4}
1 ≤ A[i] ≤ 103

expected time complexity: O(N*logN)
expected auxiliary space: O(N)

standard_solution_code:
from collections import Counter

class Solution:

	def minSteps(self, A, N, K):
		C = Counter(A)
		A = [[v, cnt] for (v, cnt) in C.items()]
		A.sort(key=lambda p: p[0])
		N = len(A)
		for i in range(N - 1, -1, -1):
			if A[i][0] - A[0][0] <= K:
				break
		i += 1
		if i >= N:
			return 0
		(allcnt, cost) = (0, 0)
		for j in range(i, N):
			allcnt += A[j][1]
			cost += (A[j][0] - A[0][0] - K) * A[j][1]
		ans = cost
		for j in range(N - 1):
			if A[N - 1][0] - A[j][0] <= K:
				break
			v = A[j][0]
			cost += v * A[j][1]
			vn = A[j + 1][0]
			diff = vn - v
			while i < N:
				if A[i][0] - vn <= K:
					cost -= (A[i][0] - v - K) * A[i][1]
					allcnt -= A[i][1]
					i += 1
				else:
					cost -= diff * allcnt
					break
			ans = min(ans, cost)
		return ans
